            _q(9, 7, 'application', 'Thầy giáo giao thử thách chạy bền vui vẻ quanh sân trường trong 3 phút. Bạn Minh hào hứng chạy nước rút thật nhanh bỏ xa các bạn hẳn nửa vòng ở phút đầu tiên, nhưng mới hết phút thứ 2 Minh đã thở dốc đứng lại không chạy nổi nữa. Lỗi của Minh là gì?', 'Minh chưa biết phân phối sức hợp lí: xuất phát quá nhanh so với sức bền bản thân khiến cạn kiệt năng lượng sớm ở phút thứ 2', ['Minh chạy quá chậm ở phút đầu tiên', 'Minh phân phối sức rất thông minh', 'Do Minh đi giày thể thao vừa chân'],
               '"Khởi đầu vừa sức – Giữ nhịp giữa đường – Bứt nhẹ cuối chặng!" là công thức phân phối sức vàng!', 'Bài học phân phối sức hợp lí khi chạy'),
            _q(9, 8, 'application', 'Lớp 3A theo dõi số vòng chạy bền nhẹ quanh sân nhỏ (1 vòng = 120 mét) của 4 nhóm rèn luyện trong 4 tuần (biểu đồ dưới ghi tổng số mét chạy được trung bình mỗi bạn trong buổi tập tuần 4). Nhóm nào rèn được sức bền tốt nhất và chạy được gấp đôi một vòng sân (240 m) cộng thêm bao nhiêu mét?', 'Nhóm 4 chạy tốt nhất (360 mét), bằng 2 vòng (240 m) cộng thêm đúng 120 mét (tức 3 vòng sân)', ['Nhóm 1 (240 mét)', 'Nhóm 2 (300 mét)', 'Nhóm 3 (280 mét)'],
               '360 - 240 = 120 mét (đúng 3 vòng sân nhỏ)! Tập đều mỗi tuần giúp sức bền của các bạn tăng vọt rõ rệt.', 'Đọc biểu đồ quãng đường chạy bền lớp 3A',
               fig=bars_fig('Quãng đường chạy bền trung bình Tuần 4 (m)', ['Nhóm 1', 'Nhóm 2', 'Nhóm 3', 'Nhóm 4'], [240, 300, 280, 360], 'm')),
            _q(9, 9, 'application', 'Nhìn đồng hồ bên dưới chỉ 5 giờ 20 phút chiều, hai bố con bạn Lan cùng chạy bộ nhẹ thư giãn quanh công viên trong 20 phút. Đến mấy giờ hai bố con kết thúc chạy để bước sang đi bộ thả lỏng 5 phút?', 'Lúc 5 giờ 40 phút chiều (và 5 giờ 45 phút kết thúc hẳn phần đi bộ thả lỏng)', ['Lúc 5 giờ 25 phút chiều', 'Lúc 6 giờ 15 phút chiều', 'Lúc 4 giờ 55 phút chiều'],
               '5 giờ 20 phút + 20 phút = 5 giờ 40 phút! Chạy bộ chiều cùng gia đình vừa khỏe tim phổi vừa gắn kết tình cảm.', 'Tính thời gian chạy bộ chiều cùng gia đình',
               fig=fig_clock(5, 20, 'Giờ bắt đầu chạy bộ nhẹ công viên')),
